<template>
  <div class="wrapper">
    <ApartmentModal
      v-if="selectItemIdx != null"
      @close="closeModal"
      :item="itemList[selectItemIdx]"
    ></ApartmentModal>
    <HeaderMenu></HeaderMenu>
    <SideMenu></SideMenu>
    <div class="content-wrapper">
      <!-- Content Header (Page header) -->
      <section class="content-header">
        <div class="container-fluid">
          <div class="row mb-2">
            <div class="col-sm-6">
              <h1>아파트/오피스텔 단지 관리</h1>
            </div>
            <div class="col-sm-6"></div>
          </div>
        </div>
        <!-- /.container-fluid -->
      </section>

      <section class="content">
        <div class="container-fluid">
          <div class="row">
            <div class="row p-2">
              <div class="col-sm-6"></div>
              <div class="col-sm-6">
                <div class="row">
                  <div class="col-sm-4">
                    <select class="form-control" v-model="searchType">
                      <option :value="null">선택</option>
                      <option>아파트 단지 이름</option>
                      <option>지역</option>
                    </select>
                  </div>
                  <div class="col-sm-8">
                    <div class="input-group">
                      <input
                        type="search"
                        class="form-control form-control-md"
                        placeholder="검색"
                        v-model="search"
                      />
                      <div class="input-group-append">
                        <button
                          type="submit"
                          class="btn btn-md btn-default"
                          @click="searchGetItem"
                        >
                          <i class="fa fa-search"></i>
                        </button>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
            <div class="col-12">
              <!-- Main content -->
              <div class="invoice p-3 mb-3">
                <!-- title row -->
                <div class="row">
                  <div class="col-sm-12">
                    <table
                      id="example1"
                      class="
                        table table-bordered table-striped
                        dataTable
                        dtr-inline
                      "
                      aria-describedby="example1_info"
                    >
                      <thead>
                        <tr>
                          <th>No</th>
                          <th>아파트단지이름</th>
                          <th>지역</th>
                          <th>동</th>
                          <th>평형</th>
                          <th>국토교통부 실거래가</th>
                          <th>네이버 호가</th>
                          <th>즐겨찾기</th>
                          <th>리뷰</th>
                          <th>리뷰작성하기</th>
                        </tr>
                      </thead>
                      <tbody>
                        <tr
                          v-for="(item, idx) in itemList"
                          v-bind:key="'i6_' + item.ApartmentId"
                        >
                          <td>{{ item.ApartmentId }}</td>
                          <td>{{ item.ApartmentName }}</td>
                          <td>{{ item.CityName }} {{ item.DvsnName }}</td>
                          <td>{{ item.SecName }}</td>
                          <td>평형</td>
                          <td>실거래</td>
                          <td>호가</td>
                          <td>{{ item.FavoriteCount }}</td>
                          <td>{{ item.ReviewCount }}</td>
                          <td
                            class="p-0 text-center"
                            style="vertical-align: middle"
                          >
                            <button
                              type="button"
                              class="btn btn-primary"
                              @click.stop
                              @click="selectItemIdx = idx"
                            >
                              작성
                            </button>
                          </td>
                        </tr>
                      </tbody>
                    </table>
                  </div>
                </div>
                <div class="row">
                  <div class="col-sm-12">
                    <Pagination
                      :pageData="pageData"
                      @paging="pagingMethod"
                    ></Pagination>
                  </div>
                </div>
              </div>
              <!-- /.invoice -->
            </div>

            <!-- /.col -->
          </div>
          <!-- /.row -->
        </div>
        <!-- /.container-fluid -->
      </section>
      <!-- /.content -->
    </div>
  </div>
</template>

<script>
import SideMenu from "./SideMenu.vue";
import HeaderMenu from "./HeaderMenu.vue";
import Pagination from "./Pagination.vue";
import ApartmentModal from "./ApartmentModal.vue";

export default {
  name: "Apartment",
  props: {},
  components: {
    SideMenu,
    HeaderMenu,
    Pagination,
    ApartmentModal,
  },
  data() {
    return {
      editMode: null,
      selectItemIdx: null,
      itemList: [],
      page: 1,
      itemCount: null,
      showViewModal: null,
      selectModal: [],
      pageData: null,
      searchType: null,
      searchType_: null,
      search: "",
      search_: "",
    };
  },
  updated() {},
  created() {
    this.init();
  },
  mounted() {},
  methods: {
    // ozit_timer_test() {
    //   window.Android.SetWebViewVisible();
    // },
    init() {
      this.getItems(this.page);
    },
    closeModal() {
      this.selectItemIdx = null;
    },
    searchGetItem() {
      this.search_ = this.search;
      this.searchType_ = this.searchType;
      this.getItems(1);
    },
    getItems(pg) {
      this.$apiGET(
        "/admin/apartments?page=" +
          pg +
          "&searchType=" +
          this.searchType_ +
          "&search=" +
          this.search_
      ).then(({ data }) => {
        this.itemList = data.d;
        this.itemCount = data.info[0].ItemCount;
        this.page = pg;

        this.pageData = this.pageDataSetting(this.itemCount, 10, 10, this.page);
      });
    },
    pageDataSetting(total, limit, block, page) {
      const totalPage = Math.ceil(total / limit);
      let currentPage = page;
      const first =
        currentPage > 1 ? parseInt(currentPage, 10) - parseInt(1, 10) : null;
      const end =
        totalPage !== currentPage
          ? parseInt(currentPage, 10) + parseInt(1, 10)
          : null;

      let startIndex = (Math.ceil(currentPage / block) - 1) * block + 1;
      let endIndex =
        startIndex + block > totalPage ? totalPage : startIndex + block - 1;
      let list = [];
      for (let index = startIndex; index <= endIndex; index++) {
        list.push(index);
      }
      return { first, end, list, currentPage };
    },
    pagingMethod(pg) {
      this.getItems(pg);
    },
  },
};
</script>
