async function _login(domain, username, password) {
  let maxCnt = 3;
  while (maxCnt > 0) {
    try {
      const re = await axios.post(domain + "/admin/auth", {
        username: username,
        password: password,
      });
      axios.defaults.headers.common["jwt"] = re.headers.jwt;
      return re;
    } catch (e) {
      maxCnt--;
    }
  }
}

function logout() {
  console.log("-------------------");
  VueCookies.remove("jwt");
}

