const local = { _login };

export default {
  local,
  install(Vue) {
    Vue.prototype.$apiGET = methods.apiGET;
    Vue.prototype.$apiPOST = methods.apiPOST;
    Vue.prototype.$login = methods.login;
    Vue.prototype.$jwtDecode = methods.jwtDecode;
    Vue.prototype.$logout = methods.logout;
  },
};
