<template>
  <div
    class="modal fade show"
    id="modal-xl"
    style="display: block; padding-right: 17px"
    aria-modal="true"
    role="dialog"
  >
    <div class="modal-dialog modal-xl">
      <div class="modal-content">
        <div class="modal-header">
          <h4 class="modal-title">1:1 문의 사항</h4>
          <button
            type="button"
            class="close"
            data-dismiss="modal"
            aria-label="Close"
          >
            <span aria-hidden="true" @click="$emit('close')">×</span>
          </button>
        </div>
        <div class="modal-body">
          <div class="callout callout-warning">
            <h5>문의:</h5>
            <br />
            <div
              v-html="tgItem.Title.replace(/(?:\r\n|\r|\n)/g, '<br />')"
            ></div>
            <!---->
            <div class="row no-print">
              <div class="col-12"></div>
            </div>
          </div>
          <div class="callout callout-info">
            <h5>회신:</h5>
            <!---->
            <div class="row no-print">
              <div class="col-12">
                <template v-if="tgEditMode == 1 && tgItem.Content != null">
                  <div
                    v-html="tgItem.Content.replace(/(?:\r\n|\r|\n)/g, '<br />')"
                  ></div>
                </template>
                <template v-else>
                  <textarea
                    v-model="tgItem.Content"
                    placeholder="답변"
                    class="form-control"
                    rows="5"
                  />
                </template>
                <br />
                <button
                  v-if="tgEditMode == 1"
                  type="button"
                  class="btn btn-success float-right"
                  style="margin-right: 5px"
                  @click="tgEditMode = 0"
                >
                  수정
                </button>
                <button
                  v-if="tgEditMode == 0"
                  type="button"
                  class="btn btn-info float-right"
                  style="margin-right: 5px"
                  @click="createNoti"
                >
                  작성
                </button>
                <button
                  v-if="tgEditMode == 1"
                  type="button"
                  class="btn btn-danger float-right"
                  style="margin-right: 5px"
                  @click="deleteNoti"
                >
                  삭제
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
      <!-- /.modal-content -->
    </div>
    <!-- /.modal-dialog -->
  </div>
</template>
<script>
export default {
  name: "QuestionsModal",
  props: { item: Object, editMode: Number },
  components: {},
  data() {
    return { tgItem: null, tgEditMode: 0 };
  },
  created() {
    // this.tgEditMode = this.editMode;
    // if (this.editMode == 0) {
    //   this.tgItem = { Title: "", Content: "" };
    // } else {
    //   this.tgItem = { ...this.item };
    // }

    this.tgItem = { ...this.item };
    if (this.tgItem.Content != null) {
      if (this.tgItem.Content.length != 0) {
        this.tgEditMode = 1;
      }
    }
  },
  mounted() {
    console.log(this.editMode);
  },
  methods: {
    createNoti() {
      if (this.tgItem.Content != null) {
        if (this.tgItem.Content.length != 0) {
          this.$apiPOST("/admin/qna", {
            Id: this.tgItem.Id,
            Content: this.tgItem.Content,
          }).then(() => {
            this.tgEditMode = 1;
            this.item.Content = this.tgItem.Content;
          });
        }
      }
    },
    deleteNoti() {
      if (this.tgItem.Content != null) {
        if (this.tgItem.Content.length != 0) {
          this.$apiPOST("/admin/qna", {
            Id: this.tgItem.Id,
          }).then(() => {
            this.tgEditMode = 0;
            this.tgItem.Content = null;
            this.item.Content = this.tgItem.Content;
          });
        }
      }
    },
  },
};
</script>
