<template>
  <div class="wrapper">
    <ReviewModal
      v-if="showModal || selectItemIdx != null"
      @close="closeModal"
      @createNotice="createNotice"
      @deleteNotice="deleteNotice"
      :item="itemList[selectItemIdx]"
      :editMode="editMode"
    ></ReviewModal>
    <HeaderMenu></HeaderMenu>
    <SideMenu></SideMenu>
    <div class="content-wrapper">
      <!-- Content Header (Page header) -->
      <section class="content-header">
        <div class="container-fluid">
          <div class="row mb-2">
            <div class="col-sm-6">
              <h1>리뷰 관리</h1>
            </div>
            <div class="col-sm-6"></div>
          </div>
        </div>
        <!-- /.container-fluid -->
      </section>

      <section class="content">
        <div class="container-fluid">
          <div class="row">
            <div class="row p-2">
              <div class="col-sm-6">
                <button
                  type="submit"
                  class="btn btn btn-primary"
                  @click="(showModal = true), (editMode = 0)"
                >
                  <i class="fas fa-pen"></i> 작성
                </button>
              </div>
              <div class="col-sm-6">
                <div class="row">
                  <div class="col-sm-4">
                    <select class="form-control" v-model="searchType">
                      <option :value="null">선택</option>
                      <option>아파트 단지 이름</option>
                      <option>지역</option>
                    </select>
                  </div>
                  <div class="col-sm-8">
                    <div class="input-group">
                      <input
                        type="search"
                        class="form-control form-control-md"
                        placeholder="검색"
                        v-model="search"
                      />
                      <div class="input-group-append">
                        <button
                          type="submit"
                          class="btn btn-md btn-default"
                          @click="searchGetItem"
                        >
                          <i class="fa fa-search"></i>
                        </button>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
            <div class="col-12">
              <!-- Main content -->
              <div class="invoice p-3 mb-3">
                <!-- title row -->
                <div class="row">
                  <div class="col-sm-12">
                    <table
                      id="example1"
                      class="
                        table table-bordered table-striped
                        dataTable
                        dtr-inline
                      "
                      aria-describedby="example1_info"
                    >
                      <thead>
                        <tr>
                          <th>No</th>
                          <th>작성자</th>
                          <th>작성일자</th>
                          <th>아파트 단지</th>
                        </tr>
                      </thead>
                      <tbody>
                        <tr
                          v-for="(item, idx) in itemList"
                          v-bind:key="'i6_' + item.ReviewId"
                          @click="(selectItemIdx = idx), (editMode = 1)"
                        >
                          <td>{{ item.ReviewId }}</td>
                          <td>{{ item.Name }}</td>
                          <td>
                            {{ $date(item.CreatedAt).format("YYYY.MM.DD") }}
                          </td>
                          <td>
                            {{ item.ApartmentName }}
                            <button
                              type="button"
                              class="btn btn-danger float-right"
                              @click.stop
                              @click="deleteNotice({ Id: item.ReviewId })"
                            >
                              삭제
                            </button>
                            <button
                              type="button"
                              class="btn btn-info float-right"
                              style="margin-right: 5px"
                              @click.stop
                              @click="(selectItemIdx = idx), (editMode = 2)"
                            >
                              수정
                            </button>
                          </td>
                        </tr>
                      </tbody>
                    </table>
                  </div>
                </div>
                <div class="row">
                  <div class="col-sm-12">
                    <Pagination
                      :pageData="pageData"
                      @paging="pagingMethod"
                    ></Pagination>
                  </div>
                </div>
              </div>
              <!-- /.invoice -->
            </div>

            <!-- /.col -->
          </div>
          <!-- /.row -->
        </div>
        <!-- /.container-fluid -->
      </section>
      <!-- /.content -->
    </div>
  </div>
</template>

<script>
import SideMenu from "./SideMenu.vue";
import HeaderMenu from "./HeaderMenu.vue";
import Pagination from "./Pagination.vue";
import ReviewModal from "../components/ReviewModal.vue";

export default {
  name: "ReviewManagement",
  props: {},
  components: {
    SideMenu,
    HeaderMenu,
    Pagination,
    ReviewModal,
  },
  data() {
    return {
      showModal: false,
      editMode: null,
      selectItemIdx: null,
      itemList: [],
      page: 1,
      itemCount: null,
      showViewModal: null,
      selectModal: [],
      pageData: null,
      searchType: null,
      searchType_: null,
      search: "",
      search_: "",
    };
  },
  updated() {},
  created() {
    this.init();
  },
  mounted() {},
  methods: {
    // ozit_timer_test() {
    //   window.Android.SetWebViewVisible();
    // },
    init() {
      this.getItems(this.page);
    },
    closeModal() {
      this.showModal = false;
      this.selectItemIdx = null;
      this.editMode = null;
    },
    searchGetItem() {
      this.search_ = this.search;
      this.searchType_ = this.searchType;
      this.getItems(1);
    },
    getItems(pg) {
      this.$apiGET(
        "/admin/reviews?page=" +
          pg +
          "&searchType=" +
          this.searchType_ +
          "&search=" +
          this.search_
      ).then(({ data }) => {
        this.itemList = data.d;
        this.itemCount = data.info[0].ItemCount;
        this.page = pg;

        this.pageData = this.pageDataSetting(this.itemCount, 10, 10, this.page);
      });
    },
    pageDataSetting(total, limit, block, page) {
      const totalPage = Math.ceil(total / limit);
      let currentPage = page;
      const first =
        currentPage > 1 ? parseInt(currentPage, 10) - parseInt(1, 10) : null;
      const end =
        totalPage !== currentPage
          ? parseInt(currentPage, 10) + parseInt(1, 10)
          : null;

      let startIndex = (Math.ceil(currentPage / block) - 1) * block + 1;
      let endIndex =
        startIndex + block > totalPage ? totalPage : startIndex + block - 1;
      let list = [];
      for (let index = startIndex; index <= endIndex; index++) {
        list.push(index);
      }
      return { first, end, list, currentPage };
    },
    pagingMethod(pg) {
      this.getItems(pg);
    },
    createNotice(item) {
      if (this.editMode == 0) {
        this.$apiPOST("/admin/review/add", item).then(() => {
          this.getItems(this.page);
          this.closeModal();
        });
      } else {
        this.$apiPOST("/admin/review/edit", item).then(() => {
          this.getItems(this.page);
          this.closeModal();
        });
      }
    },
    deleteNotice(item) {
      this.$apiPOST("/admin/review/delete", item).then(() => {
        this.getItems(this.page);
        this.closeModal();
      });
    },
  },
};
</script>
