<template>
  <div class="wrapper">
    <QuestionsModal
      v-if="showModal || selectItemIdx != null"
      @close="closeModal"
      :item="itemList[selectItemIdx]"
    ></QuestionsModal>
    <HeaderMenu></HeaderMenu>
    <SideMenu></SideMenu>
    <div class="content-wrapper">
      <!-- Content Header (Page header) -->
      <section class="content-header">
        <div class="container-fluid">
          <div class="row mb-2">
            <div class="col-sm-6">
              <h1>1:1 문의 사항</h1>
            </div>
            <div class="col-sm-6"></div>
          </div>
        </div>
        <!-- /.container-fluid -->
      </section>

      <section class="content">
        <div class="container-fluid">
          <div class="row">
            <div class="row p-2">
              <div class="col-sm-12">
                <button
                  v-if="pageType"
                  type="button"
                  class="btn btn-info float-left"
                  style="margin-left: 5px"
                  @click="changePageType(false)"
                >
                  <i class="fas fa-sign-out-alt"></i> 전체 리스트
                </button>
                <button
                  v-else
                  type="button"
                  class="btn btn-danger float-left"
                  style="margin-left: 5px"
                  @click="changePageType(true)"
                >
                  <i class="fas fa-sign-out-alt"></i> 미회신만 모아보기
                </button>
              </div>
            </div>
            <div class="col-12">
              <!-- Main content -->
              <div class="invoice p-3 mb-3">
                <!-- title row -->
                <div class="row">
                  <div class="col-sm-12">
                    <table
                      id="example1"
                      class="
                        table table-bordered table-striped
                        dataTable
                        dtr-inline
                      "
                      aria-describedby="example1_info"
                    >
                      <thead>
                        <tr>
                          <th>No</th>
                          <th>작성일자</th>
                          <th>작성자</th>
                          <th>회신여부</th>
                          <th>제목</th>
                        </tr>
                      </thead>
                      <tbody>
                        <tr
                          v-for="(item, idx) in itemList"
                          v-bind:key="'i2_' + item.Id"
                          @click="selectItemIdx = idx"
                        >
                          <td>{{ item.Id }}</td>
                          <td>
                            {{ $date(item.CreatedAt).format("YYYY.MM.DD") }}
                          </td>
                          <td>
                            {{ item.Contact }}
                          </td>
                          <td>
                            {{
                              item.Content == null
                                ? "미회신"
                                : item.Content.length == 0
                                ? "미회신"
                                : "회신"
                            }}
                          </td>
                          <td>
                            {{ item.Title }}
                          </td>
                        </tr>
                      </tbody>
                    </table>
                  </div>
                </div>
                <div class="row">
                  <div class="col-sm-12">
                    <Pagination
                      :pageData="pageData"
                      @paging="pagingMethod"
                    ></Pagination>
                  </div>
                </div>
              </div>
              <!-- /.invoice -->
            </div>

            <!-- /.col -->
          </div>
          <!-- /.row -->
        </div>
        <!-- /.container-fluid -->
      </section>
      <!-- /.content -->
    </div>
  </div>
</template>

<script>
import SideMenu from "./SideMenu.vue";
import HeaderMenu from "./HeaderMenu.vue";
import Pagination from "./Pagination.vue";
import QuestionsModal from "../components/QuestionsModal";

export default {
  name: "Questions",
  props: {},
  components: {
    SideMenu,
    HeaderMenu,
    Pagination,
    QuestionsModal,
  },
  data() {
    return {
      pageType: false,
      editMode: null,
      selectItemIdx: null,
      itemList: [],
      page: 1,
      itemCount: null,
      showModal: false,
      showViewModal: null,
      selectModal: [],
      pageData: null,
    };
  },
  updated() {},
  created() {
    this.init();
  },
  mounted() {},
  methods: {
    // ozit_timer_test() {
    //   window.Android.SetWebViewVisible();
    // },
    init() {
      this.getItems(this.page);
    },
    closeModal() {
      this.showModal = false;
      this.selectItemIdx = null;
    },
    changePageType(ty) {
      this.pageType = ty;
      this.getItems(1);
    },
    getItems(pg) {
      if (this.pageType) {
        this.$apiGET("/admin/qnas/nc?page=" + pg).then(({ data }) => {
          this.itemList = data.d;
          this.itemCount = data.info[0].ItemCount;
          this.page = pg;

          this.pageData = this.pageDataSetting(
            this.itemCount,
            10,
            10,
            this.page
          );
        });
      } else {
        this.$apiGET("/admin/qnas?page=" + pg).then(({ data }) => {
          this.itemList = data.d;
          this.itemCount = data.info[0].ItemCount;
          this.page = pg;

          this.pageData = this.pageDataSetting(
            this.itemCount,
            10,
            10,
            this.page
          );
        });
      }
    },
    pageDataSetting(total, limit, block, page) {
      const totalPage = Math.ceil(total / limit);
      let currentPage = page;
      const first =
        currentPage > 1 ? parseInt(currentPage, 10) - parseInt(1, 10) : null;
      const end =
        totalPage !== currentPage
          ? parseInt(currentPage, 10) + parseInt(1, 10)
          : null;

      let startIndex = (Math.ceil(currentPage / block) - 1) * block + 1;
      let endIndex =
        startIndex + block > totalPage ? totalPage : startIndex + block - 1;
      let list = [];
      for (let index = startIndex; index <= endIndex; index++) {
        list.push(index);
      }
      return { first, end, list, currentPage };
    },
    pagingMethod(pg) {
      this.getItems(pg);
    },
  },
};
</script>
