<template>
  <ul class="pagination text-center" style="justify-content: center">
    <template v-if="pageData != null && pageData.list.length != 0">
      <li
        class="paginate_button page-item previous"
        id="example1_previous"
        v-bind:class="{ disabled: pageData.first == null }"
        @click="pageData.first !== null ? sendPage(pageData.first) : ''"
      >
        <button aria-controls="example1" class="page-link">
          <i class="fas fa-caret-left"></i>
        </button>
      </li>
      <li
        v-for="pg in pageData.list"
        v-bind:key="'pg_' + pg"
        class="paginate_button page-item"
        v-bind:class="{ active: pg == pageData.currentPage }"
        @click="sendPage(pg)"
      >
        <button aria-controls="example1" class="page-link">{{ pg }}</button>
      </li>
      <li
        class="paginate_button page-item next"
        id="example1_next"
        v-bind:class="{ disabled: pageData.end == null }"
        @click="pageData.end !== null ? sendPage(pageData.end) : ''"
      >
        <button aria-controls="example1" class="page-link">
          <i class="fas fa-caret-right"></i>
        </button>
      </li>
    </template>
  </ul>
</template>
<script>
export default {
  name: "Pagination",
  props: {
    pageData: Object,
  },
  components: {},
  data() {
    return {};
  },
  created() {
    // this.pageData = this.pageDataSetting(
    //   this.total,
    //   this.limit,
    //   this.block,
    //   this.page
    // );
  },
  mounted() {},
  methods: {
    sendPage(page) {
      this.$emit("paging", page);
    },
  },
};
</script>
