<template>
  <div class="wrapper">
    <ConsultManagementModal
      v-if="selectItemIdx != null"
      @close="closeModal"
      @editAdmin="editAdmin"
      @addAdmin="addAdmin"
      :item="editMode ? itemList[selectItemIdx] : null"
      :editMode="editMode"
      :pageType="1"
    ></ConsultManagementModal>
    <HeaderMenu></HeaderMenu>
    <SideMenu></SideMenu>
    <div class="content-wrapper">
      <!-- Content Header (Page header) -->
      <section class="content-header">
        <div class="container-fluid">
          <div class="row mb-2">
            <div class="col-sm-6">
              <h1>팀 관리</h1>
            </div>
            <div class="col-sm-6"></div>
          </div>
        </div>
        <!-- /.container-fluid -->
      </section>

      <section class="content">
        <div class="container-fluid">
          <div class="row">
            <div class="row p-2">
              <div class="col-sm-6">
                <button
                  type="button"
                  class="btn btn-primary float-left"
                  style="margin-left: 5px"
                  @click="(selectItemIdx = 1), (editMode = false)"
                >
                  팀장추가
                </button>
              </div>
              <div class="col-sm-6">
                <div class="row">
                  <div class="col-sm-4"></div>
                  <div class="col-sm-8">
                    <div class="input-group">
                      <input
                        type="search"
                        class="form-control form-control-md"
                        placeholder="팀장 검색"
                        v-model="search"
                      />
                      <div class="input-group-append">
                        <button
                          type="submit"
                          class="btn btn-md btn-default"
                          @click="searchGetItem"
                        >
                          <i class="fa fa-search"></i>
                        </button>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
            <div class="col-12">
              <!-- Main content -->
              <div class="invoice p-3 mb-3">
                <!-- title row -->
                <div class="row">
                  <div class="col-sm-12">
                    <table
                      id="example1"
                      class="
                        table table-bordered table-striped
                        dataTable
                        dtr-inline
                      "
                      aria-describedby="example1_info"
                    >
                      <thead>
                        <tr>
                          <th>No</th>
                          <th>팀장</th>
                          <th>팀원수</th>
                          <th>ID</th>
                          <th>PW</th>
                          <th>상담배정(월)</th>
                          <th>상담배정(주)</th>
                          <th>탈퇴/수정</th>
                        </tr>
                      </thead>
                      <tbody>
                        <tr
                          v-for="(item, idx) in itemList"
                          v-bind:key="'i9_' + item.Id"
                        >
                          <td>{{ item.Id }}</td>
                          <td>{{ item.Name }}</td>
                          <td>{{ item.TeamMemberCount }}</td>
                          <td>{{ item.Username }}</td>
                          <td>{{ item.Password }}</td>
                          <td>{{ item.MonthlyConsult }}</td>
                          <td>{{ item.WeeklyConsult }}</td>
                          <td
                            class="p-0 text-center"
                            style="vertical-align: middle"
                          >
                            <button
                              type="button"
                              class="btn"
                              v-bind:class="{
                                'btn-outline-secondary': item.IsActive == 0,
                                'btn-danger': item.IsActive == 1,
                              }"
                              @click.stop
                              @click="deactivate(item)"
                            >
                              탈퇴
                            </button>
                            <button
                              type="button"
                              class="btn btn-success"
                              style="margin-left: 5px"
                              @click.stop
                              @click="(selectItemIdx = idx), (editMode = true)"
                            >
                              수정
                            </button>
                          </td>
                        </tr>
                      </tbody>
                    </table>
                  </div>
                </div>
                <div class="row">
                  <div class="col-sm-12">
                    <Pagination
                      :pageData="pageData"
                      @paging="pagingMethod"
                    ></Pagination>
                  </div>
                </div>
              </div>
              <!-- /.invoice -->
            </div>

            <!-- /.col -->
          </div>
          <!-- /.row -->
        </div>
        <!-- /.container-fluid -->
      </section>
      <!-- /.content -->
    </div>
  </div>
</template>

<script>
import SideMenu from "./SideMenu.vue";
import HeaderMenu from "./HeaderMenu.vue";
import Pagination from "./Pagination.vue";
import ConsultManagementModal from "./ConsultManagementModal.vue";

export default {
  name: "TeamManagement",
  props: {},
  components: {
    SideMenu,
    HeaderMenu,
    Pagination,
    ConsultManagementModal,
  },
  data() {
    return {
      editMode: null,
      selectItemIdx: null,
      itemList: [],
      page: 1,
      itemCount: null,
      showViewModal: null,
      selectModal: [],
      pageData: null,
      search: "",
      search_: "",
    };
  },
  updated() {},
  created() {
    this.init();
  },
  mounted() {},
  methods: {
    // ozit_timer_test() {
    //   window.Android.SetWebViewVisible();
    // },
    init() {
      this.getItems(this.page);
    },
    closeModal() {
      this.selectItemIdx = null;
    },
    searchGetItem() {
      this.search_ = this.search;
      this.getItems(1);
    },
    getItems(pg) {
      this.$apiGET(
        "/admin/admins2/team?page=" + pg + "&search=" + this.search_
      ).then(({ data }) => {
        this.itemList = data.d;
        this.itemCount = data.info[0].ItemCount;
        this.page = pg;

        this.pageData = this.pageDataSetting(this.itemCount, 10, 10, this.page);
      });
    },
    pageDataSetting(total, limit, block, page) {
      const totalPage = Math.ceil(total / limit);
      let currentPage = page;
      const first =
        currentPage > 1 ? parseInt(currentPage, 10) - parseInt(1, 10) : null;
      const end =
        totalPage !== currentPage
          ? parseInt(currentPage, 10) + parseInt(1, 10)
          : null;

      let startIndex = (Math.ceil(currentPage / block) - 1) * block + 1;
      let endIndex =
        startIndex + block > totalPage ? totalPage : startIndex + block - 1;
      let list = [];
      for (let index = startIndex; index <= endIndex; index++) {
        list.push(index);
      }
      return { first, end, list, currentPage };
    },
    pagingMethod(pg) {
      this.getItems(pg);
    },
    editAdmin(item) {
      this.$apiPOST("/admin/teamleader/edit", item).then(() => {
        this.getItems(this.page);
        this.closeModal();
      });
    },
    deactivate(item) {
      this.$apiPOST("/admin/admins2/deactivate", {
        Id: item.Id,
        IsActive: !item.IsActive,
      }).then(() => {
        this.getItems(this.page);
      });
    },
    addAdmin(item) {
      this.$apiPOST("/admin/teamleader/add", item).then(() => {
        this.getItems(this.page);
        this.closeModal();
      });
    },
  },
};
</script>
